import { resourceQuanta } from './resource-quantities.js';
import { MAX_RESOURCE_U } from './resource-definitions.js';
import { DEPOSIT_KINDS, HYDROGEN_SOURCE_TYPES } from './body-resource-profiles.js';
import { validateGradeProbabilities, weightedGradeMean, resourceRandom } from './ore-quality.js';
const check=(condition,message)=>{if(!condition)throw Error(message);};
const obj=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
function keys(v,allowed,label){check(obj(v),label+' 객체 오류');for(const k of Object.keys(v))check(allowed.includes(k),label+' 알 수 없는 키: '+k);}
const num=(n,min,max,label)=>check(typeof n==='number'&&Number.isFinite(n)&&n>=min&&n<=max,label+' 범위 오류');
const id=v=>typeof v==='string'&&/^[A-Za-z0-9_:.-]{1,100}$/.test(v);
export function oreDeposits(template){return Object.entries(template.geology.cells).flatMap(([tileId,g])=>(g.deposits??[]).filter(d=>d.resourceId==='ore').map(d=>({...d,tileId})));}
export function summarizeOre(template){const deposits=oreDeposits(template),types={};let totalQuanta=0;for(const kind of DEPOSIT_KINDS.keys()){const list=deposits.filter(d=>d.depositKind===kind),quanta=list.reduce((n,d)=>n+Math.round(d.initialReserveU*1000),0);totalQuanta+=quanta;types[kind]={quanta,totalU:quanta/1000,gradeMean:weightedGradeMean(list),deposits:list.length,groups:new Set(list.map(d=>d.groupId)).size};}return {totalQuanta,totalU:totalQuanta/1000,gradeMean:weightedGradeMean(deposits),types,depositCount:deposits.length};}
export function validateResourceConfiguration(c){keys(c,['generatorVersion','worldSeed','budgetPolicy','totalOreU','typeShares','gradeTargets','jitter','certainty','notes','placementPolicy','extractionFloor','processingFloor'],'자원 설정');check(c.generatorVersion===1,'자원 생성기 버전 오류');check(typeof c.worldSeed==='string'&&c.worldSeed.length<=200,'세계 시드 오류');check(['fixed','procedural','manual'].includes(c.budgetPolicy),'자원 예산 정책 오류');num(c.totalOreU,0,MAX_RESOURCE_U,'광석 목표');resourceQuanta(c.totalOreU);keys(c.typeShares,[...DEPOSIT_KINDS.keys()],'매장형 비율');for(const k of ['surface','vein','deep'])num(c.typeShares[k],0,1,'매장형 비율');check(Math.abs(Object.values(c.typeShares).reduce((a,b)=>a+b,0)-1)<1e-9,'매장형 합계 100%');keys(c.gradeTargets,[...DEPOSIT_KINDS.keys()],'품질 타깃');for(const k of Object.keys(c.typeShares))validateGradeProbabilities(c.gradeTargets[k]);for(const k of ['extractionFloor','processingFloor'])if(c[k]!==undefined)num(c[k],0,100,'난도 하한');if(c.placementPolicy!==undefined){keys(c.placementPolicy,['veinPreferredLandThreshold','oceanSurfaceWaterThreshold','oceanExtractionFloor','oceanDiscoveryTierMin'],'배치 정책');num(c.placementPolicy.veinPreferredLandThreshold,0,1,'육지 기준');num(c.placementPolicy.oceanSurfaceWaterThreshold,0,1,'해양 기준');num(c.placementPolicy.oceanExtractionFloor,0,100,'단괴 채굴 난도');check(Number.isInteger(c.placementPolicy.oceanDiscoveryTierMin)&&c.placementPolicy.oceanDiscoveryTierMin>=0&&c.placementPolicy.oceanDiscoveryTierMin<=5,'단괴 탐사 티어');}num(c.jitter,0,.2,'품질 편차');check(['confirmed','mixed','provisional','local-alternative','legacy'].includes(c.certainty),'확정/잠정 분류 오류');check(typeof c.notes==='string'&&c.notes.length<=1000,'자원 메모 오류');return true;}
export function validateExtendedDeposit(d){
 if(d.resourceId!=='ore')return;check(DEPOSIT_KINDS.has(d.depositKind),'등록되지 않은 매장 형태');check(id(d.groupId),'광맥 그룹 ID 오류');validateGradeProbabilities(d.gradeProbabilities);num(d.processingDifficulty,0,100,'가공 난도');num(d.accessDepth,0,100,'상대 심도');check(Array.isArray(d.compositionTags)&&d.compositionTags.length<=16&&d.compositionTags.every(id),'미래 성분 태그 오류');resourceQuanta(d.initialReserveU);
}
export function validateResourceContract(template,grid,body){
 if(template.migration!==undefined){keys(template.migration,['migrationVersion','fromSchemaVersion','notes'],'이관');check(template.migration.migrationVersion===1&&template.migration.fromSchemaVersion===1&&typeof template.migration.notes==='string','이관 버전/메모 오류');}
 const deposits=oreDeposits(template);for(const d of deposits)validateExtendedDeposit(d);
 check(!(body.surfaceType==='atmosphere'||/가스|거대|giant/i.test(body.type??''))||deposits.length===0,'대기 기준층에는 암석 ore를 배치할 수 없습니다.');
 const groups=new Map();for(const d of deposits){const prior=groups.get(d.groupId);check(!prior||prior.kind===d.depositKind,'광맥 그룹의 형태가 혼재합니다.');if(!prior)groups.set(d.groupId,{kind:d.depositKind,ids:new Set()});groups.get(d.groupId).ids.add(d.tileId);}
 for(const {kind,ids}of groups.values())if(kind==='vein'){const visited=new Set(),stack=[ids.values().next().value];while(stack.length){const id=stack.pop();if(visited.has(id))continue;visited.add(id);for(const n of grid.byId.get(id).neighborIds)if(ids.has(n)&&!visited.has(n))stack.push(n);}check(visited.size===ids.size,'광맥 그룹은 구면 이웃으로 연결되어야 합니다.');}
 const cfg=template.resourceConfiguration;if(cfg!==null){validateResourceConfiguration(cfg);const s=summarizeOre(template);check(s.totalQuanta===Math.round(cfg.totalOreU*1000),'광석 실제 총량/설정 불일치');for(const kind of Object.keys(cfg.typeShares)){const t=s.types[kind];check(Math.abs(t.quanta-s.totalQuanta*cfg.typeShares[kind])<=1.01,'형태별 예산 불일치: '+kind);if(t.gradeMean)for(const k of ['low','medium','high'])check(Math.abs(t.gradeMean[k]-cfg.gradeTargets[kind][k])<=1e-6,'매장량 가중 품질 평균 불일치: '+kind);}}
 check(Array.isArray(template.hydrogenSources)&&template.hydrogenSources.length<=128,'수소 공급원 배열 오류');const sourceIds=new Set();for(const s of template.hydrogenSources){keys(s,['sourceId','tileId','resourceId','sourceType','initialReserveU','potentialCollectionUPerCycle','operatingDifficulty','facilityRequirement','notes'],'수소 공급원');check(id(s.sourceId)&&!sourceIds.has(s.sourceId)&&grid.byId.has(s.tileId),'수소 공급원 ID/구역 오류');sourceIds.add(s.sourceId);check(s.resourceId==='hydrogen'&&HYDROGEN_SOURCE_TYPES.has(s.sourceType),'수소 공급원 유형 오류');if(s.sourceType==='finite-source')num(s.initialReserveU,0,MAX_RESOURCE_U,'유한 수소 원천');else check(s.initialReserveU===null,'대기 채집원은 무한/유한 매장량으로 저장하지 않습니다.');check(s.potentialCollectionUPerCycle===null,'현재 채집 생산량은 미확정');num(s.operatingDifficulty,0,100,'채집 접근 난도');check(typeof s.facilityRequirement==='string'&&typeof s.notes==='string','공급원 메모 오류');}
 check(Array.isArray(template.initialResourceKnowledge)&&template.initialResourceKnowledge.length<=64,'초기 자원 지식 오류');const allIds=new Set(deposits.map(d=>d.depositId)),civs=new Set();for(const k of template.initialResourceKnowledge){keys(k,['civilizationId','tiers','deposits'],'문명별 초기 자원 지식');check(id(k.civilizationId)&&!civs.has(k.civilizationId),'문명 ID 중복/오류');civs.add(k.civilizationId);check(Array.isArray(k.tiers)&&Array.isArray(k.deposits),'문명 지식 배열 오류');const tiers=new Set(),seen=new Set();for(const t of k.tiers){keys(t,['tier','surveyProgress'],'탐사 티어');check(Number.isInteger(t.tier)&&t.tier>=0&&t.tier<=5&&!tiers.has(t.tier),'탐사 티어 오류');tiers.add(t.tier);num(t.surveyProgress,0,1,'티어 조사 진행');}for(const d of k.deposits){keys(d,['depositId','detectedFraction','confirmedFraction','gradeConfidence','estimatedGradeProbabilities'],'매장지 인지');check(allIds.has(d.depositId)&&!seen.has(d.depositId),'초기 인지의 매장지 참조 오류');seen.add(d.depositId);for(const f of ['detectedFraction','confirmedFraction','gradeConfidence'])num(d[f],0,1,'인지율');check(d.confirmedFraction<=d.detectedFraction,'확인율은 탐지율 이하');if(d.estimatedGradeProbabilities!==null)validateGradeProbabilities(d.estimatedGradeProbabilities);}}
 return true;
}
// Explicit editor application creates a local alternative; static official snapshots never change.
export function refreshAlternativeResourceConfiguration(template){if(template.schemaVersion!==2)return template;for(const g of Object.values(template.geology.cells))for(const d of g.deposits??[])if(d.resourceId==='ore'&&!d.depositKind)Object.assign(d,{depositKind:'surface',groupId:'manual-'+d.depositId.slice(0,60)+'-'+Math.floor(resourceRandom(d.depositId)*2**32).toString(16),gradeProbabilities:{low:.6,medium:.38,high:.02},processingDifficulty:30,accessDepth:0,compositionTags:[]});
 const complete=Object.keys(template.geology.cells).length===template.grid.cellCount&&Object.values(template.geology.cells).every(g=>g.deposits!==null);if(!complete){template.resourceConfiguration=null;return template;}
 const s=summarizeOre(template),cfg=template.resourceConfiguration??{generatorVersion:1,worldSeed:'manual-v1-migration',budgetPolicy:'manual',totalOreU:s.totalU,typeShares:{surface:1,vein:0,deep:0},gradeTargets:Object.fromEntries(['surface','vein','deep'].map(k=>[k,{low:.6,medium:.38,high:.02}])),jitter:0,certainty:'local-alternative',notes:''};template.resourceConfiguration=cfg;cfg.totalOreU=s.totalU;cfg.budgetPolicy='manual';cfg.certainty='local-alternative';cfg.notes='로컬 수동 대안 · 공식 프리셋은 변경하지 않음';for(const k of ['surface','vein','deep']){cfg.typeShares[k]=s.totalQuanta?s.types[k].quanta/s.totalQuanta:(k==='surface'?1:0);if(s.types[k].gradeMean)cfg.gradeTargets[k]=s.types[k].gradeMean;}
 return template;
}
